export type MichelinTier = "3 Stars" | "2 Stars" | "1 Star" | "Bib Gourmand" | "Michelin Selected";

export type Restaurant = {
  name: string;
  rating: number;
  reviews: string;
  reviewsCount: number;
  priceMin: number;
  priceMax: number;
  cuisine: string;
  category: string;
  area: string;
  address: string;
  phone: string;
  hours: string;
  status: "Open" | "Closed";
  image: string;
  latitude: number;
  longitude: number;
  features: string[]; // ["Dine-in", "Takeaway", "Delivery"]
  description: string;
  website: string;
  michelin?: MichelinTier;
  liquor?: "Licensed" | "Non-Licensed" | "BYOB";
  seatingPerks?: string[];
  occasions?: string[];
  logistics?: string[];
  bookingPlatform?: { name: "SevenRooms" | "OpenTable" | "Direct Website"; url: string };
  deliveryLinks?: { deliveroo?: string; talabat?: string; noon?: string; careem?: string; keeta?: string };
  barType?: string;
  eateryType?: "restaurant" | "bar" | "cafe";
  slug?: string;
};

export type SponsoredRestaurant = {
  name: string;
  rating: number;
  reviewsCount: number;
  category: string;
  statusText: string;
  distance: string;
  floor?: string;
  images: string[];
  tagline?: string;
  website: string;
  phone: string;
  address: string;
};

